use smart_engine::{SmartProvider,SmartctlProvider};
use safety_policy::{EndpointKind,JobKind,OperationPlan,PlanConfirmation,StorageEndpoint};
#[tauri::command]fn list_storage_devices()->Result<Vec<decode_core::DeviceIdentity>,String>{device_discovery::discover_devices().map_err(|e|e.to_string())}
#[tauri::command]fn inspect_smart(device:decode_core::DeviceIdentity)->Result<diagnostic_engine::DiagnosticSnapshot,String>{SmartctlProvider::default().inspect_read_only(&device).map_err(|e|e.to_string())}
fn plan(kind:JobKind,source:StorageEndpoint,destination:StorageEndpoint,n:u64)->OperationPlan{OperationPlan{job_kind:kind,source,destination,requested_bytes:n}}
#[tauri::command]fn operation_confirmation_phrase(kind:JobKind,source:StorageEndpoint,destination:StorageEndpoint,requested_bytes:u64)->Result<String,String>{plan(kind,source,destination,requested_bytes).confirmation_phrase().map_err(|e|e.to_string())}
#[tauri::command]fn clone_physical_disk(source:StorageEndpoint,destination:StorageEndpoint,requested_bytes:u64,confirmation_phrase:String)->Result<clone_engine::CopyReport,String>{let p=plan(JobKind::BlockClone,source,destination,requested_bytes);let c=PlanConfirmation::confirm(&p,&confirmation_phrase).map_err(|e|e.to_string())?;clone_engine::clone_block_device(&p,&c).map_err(|e|e.to_string())}
#[tauri::command]fn create_disk_image(source:StorageEndpoint,image_path:String,destination_storage_identity:String,capacity_bytes:u64)->Result<imaging_engine::ImageReport,String>{imaging_engine::create_raw_image(&source,std::path::Path::new(&image_path),&destination_storage_identity,capacity_bytes).map_err(|e|e.to_string())}
#[tauri::command]fn restore_disk_image(image_source:StorageEndpoint,destination:StorageEndpoint,image_path:String,image_bytes:u64,confirmation_phrase:String)->Result<imaging_engine::ImageReport,String>{let p=plan(JobKind::Restore,image_source,destination,image_bytes);let c=PlanConfirmation::confirm(&p,&confirmation_phrase).map_err(|e|e.to_string())?;imaging_engine::restore_raw_image(&p,&c,std::path::Path::new(&image_path)).map_err(|e|e.to_string())}
#[tauri::command]fn run_ddrescue(source:StorageEndpoint,destination_storage_identity:String,image_path:String,mapfile_path:String,requested_bytes:u64,confirmation_phrase:String)->Result<recovery_engine::DdrescueReport,String>{
let dest=StorageEndpoint{kind:EndpointKind::ImageFile,path:image_path.clone(),stable_identity:Some(destination_storage_identity.clone()),capacity_bytes:requested_bytes,is_system:false,is_mounted:false,is_read_only:false};
let p=plan(JobKind::DiskImage,source.clone(),dest,requested_bytes);let c=PlanConfirmation::confirm(&p,&confirmation_phrase).map_err(|e|e.to_string())?;c.validate_for(&p).map_err(|e|e.to_string())?;
let dp=recovery_engine::DdrescuePlan{source,destination_image_path:image_path,destination_storage_identity,mapfile_path};recovery_engine::run_ddrescue_first_pass(&dp).map_err(|e|e.to_string())}
#[tauri::command]fn recover_files_photorec(source:StorageEndpoint,destination:StorageEndpoint,output_directory:String,requested_bytes:u64,confirmation_phrase:String)->Result<file_recovery_engine::PhotoRecReport,String>{
let p=plan(JobKind::FileRecovery,source.clone(),destination.clone(),requested_bytes);let c=PlanConfirmation::confirm(&p,&confirmation_phrase).map_err(|e|e.to_string())?;c.validate_for(&p).map_err(|e|e.to_string())?;
let rp=file_recovery_engine::FileRecoveryPlan{source,destination,output_directory};rp.validate_photorec().map_err(|e|e.to_string())?;file_recovery_engine::recover_with_photorec(&rp).map_err(|e|e.to_string())}
#[cfg_attr(mobile,tauri::mobile_entry_point)]pub fn run(){tauri::Builder::default().invoke_handler(tauri::generate_handler![list_storage_devices,inspect_smart,operation_confirmation_phrase,clone_physical_disk,create_disk_image,restore_disk_image,run_ddrescue,recover_files_photorec]).run(tauri::generate_context!()).expect("error while running Decode Disk Doctor");}
